192	    private Map<Long, List<Snapshot>> snapshots(String sheetId, Long personId, String table) {
193	        Map<Long, List<Snapshot>> snapshots = new HashMap<>();
194	        jdbc.query("SELECT person_id, left_day, due_total FROM " + table + " WHERE sheet_id = ?"
195	                + (personId == null ? "" : " AND person_id = " + personId) + " ORDER BY id", rs -> {
196	                    snapshots.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(new Snapshot(
197	                            rs.getObject("left_day", LocalDate.class), rs.getString("due_total")));
198	                }, sheetId);
199	        return snapshots;
200	    }
