207	    private List<Person> queryFrom(String sheetId, Long personId, String gradeTable, String holdTable,
208	            String aliasTable, String retirementTable, String snapshotTable, String sql, Object... args) {
209	        Map<Long, NavigableMap<LocalDate, String>> grades = grades(sheetId, personId, gradeTable);
210	        Map<Long, List<Hold>> holds = holds(sheetId, personId, holdTable);
211	        Map<Long, List<String>> aliases = aliases(sheetId, personId, aliasTable);
212	        Map<Long, List<PastRetirement>> past = pastRetirements(sheetId, personId, retirementTable);
213	        Map<Long, List<Snapshot>> snapshots = snapshots(sheetId, personId, snapshotTable);
214	        RowMapper<Person> row = (rs, i) -> {
215	            Person p = new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
216	                    grades.getOrDefault(rs.getLong("id"), new TreeMap<>()), rs.getLong("version"),
217	                    rs.getObject("retired_from", LocalDate.class), holds.getOrDefault(rs.getLong("id"), List.of()));
218	            p.setTerms(rs.getObject("terms", Integer.class));
219	            p.setContact(rs.getString("contact"));
220	            p.setTags(rs.getString("tags"));
221	            p.setOrigin(rs.getString("origin"));
222	            p.getAliases().addAll(aliases.getOrDefault(rs.getLong("id"), List.of()));
223	            p.getPastRetirements().addAll(past.getOrDefault(rs.getLong("id"), List.of()));
224	            p.getSnapshots().addAll(snapshots.getOrDefault(rs.getLong("id"), List.of()));
225	            return p;
226	        };
227	        return jdbc.query(sql, row, args);
228	    }
