345	    /** Adds the person as {@link #add(String, String, String, Integer, String)} does, with their tags as stored
346	     *  (null for none). */
347	    public Person add(String sheetId, String name, String grade, Integer terms, String contact, String tags) {
348	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
349	        jdbc.update(con -> {
350	            PreparedStatement ps = con.prepareStatement(
351	                    "INSERT INTO person (sheet_id, name, terms, contact, tags, list_position) VALUES (?, ?, ?, ?, ?, (SELECT"
352	                    + " COALESCE(MAX(list_position), 0) + 1 FROM person WHERE sheet_id = ?))", new String[] { "ID" });
353	            ps.setString(1, sheetId);
354	            ps.setString(2, name);
355	            ps.setObject(3, terms, java.sql.Types.INTEGER);
356	            ps.setString(4, contact);
357	            ps.setString(5, tags);
358	            ps.setString(6, sheetId);
359	            return ps;
360	        }, keys);
361	        long id = keys.getKey().longValue();
362	        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)", sheetId,
363	                id, Person.START, grade);
364	        Person person = new Person(id, sheetId, name, new TreeMap<>(Map.of(Person.START, grade)), 0);
365	        person.setTerms(terms);
366	        person.setContact(contact);
367	        person.setTags(tags);
368	        return person;
369	    }
