371	    /**
372	     * Stores the person over the version it was loaded at, moving the version on; false (nothing
373	     * stored) when someone else has stored another version since. The grade the edit records (if any)
374	     * is kept with the ones already recorded, replacing one from the same date.
375	     */
376	    public boolean save(Person person) {
377	        int n = jdbc.update(
378	                "UPDATE person SET name = ?, terms = ?, contact = ?, tags = ?, version = version + 1 WHERE sheet_id = ? AND id = ? AND version = ?",
379	                person.getName(), person.getTerms(), person.getContact(), person.getTags(), person.getSheetId(), person.getId(), person.getVersion());
380	        if (n == 1) {
381	            person.setVersion(person.getVersion() + 1);
382	            LocalDate from = person.getRecordFrom();
383	            if (from != null) {
384	                jdbc.update("MERGE INTO person_grade (sheet_id, person_id, from_date, grade) KEY (person_id, from_date)"
385	                        + " VALUES (?, ?, ?, ?)", person.getSheetId(), person.getId(), from, person.getGrades().get(from));
386	            }
387	        }
388	        return n == 1;
389	    }
