391	    /**
392	     * Swaps the person with their neighbour in the list (the one above when {@code up}, else the one below);
393	     * answers the person's new position in the list, counting from 1, or 0 (nothing stored) when there is no
394	     * neighbour that way: the top cannot move up, nor the bottom down. An edit of them leaves it as it is.
395	     */
396	    public int move(Person person, boolean up) {
397	        List<long[]> order = jdbc.query("SELECT id, list_position FROM person WHERE sheet_id = ? ORDER BY list_position, id"
398	                + " FOR UPDATE", (rs, i) -> new long[] { rs.getLong("id"), rs.getLong("list_position") },
399	                person.getSheetId());
400	        int at = -1;
401	        for (int i = 0; i < order.size(); i++) {
402	            if (order.get(i)[0] == person.getId()) {
403	                at = i;
404	            }
405	        }
406	        int to = up ? at - 1 : at + 1;
407	        if (at < 0 || to < 0 || to >= order.size()) {
408	            return 0;
409	        }
410	        long[] mine = order.get(at);
411	        long[] theirs = order.get(to);
412	        if (mine[1] == theirs[1]) {
413	            // tied positions (never made by this store): number them apart first, so the swap moves them
414	            renumber(person.getSheetId(), order);
415	            return move(person, up);
416	        }
417	        jdbc.update("UPDATE person SET list_position = ? WHERE sheet_id = ? AND id = ?", theirs[1], person.getSheetId(),
418	                mine[0]);
419	        jdbc.update("UPDATE person SET list_position = ? WHERE sheet_id = ? AND id = ?", mine[1], person.getSheetId(),
420	                theirs[0]);
421	        return to + 1;
422	    }
423	
424	    /** Gives the people positions 1, 2, ... in their present order. */
425	    private void renumber(String sheetId, List<long[]> order) {
426	        for (int i = 0; i < order.size(); i++) {
427	            jdbc.update("UPDATE person SET list_position = ? WHERE sheet_id = ? AND id = ?", i + 1, sheetId, order.get(i)[0]);
428	        }
429	    }
