461	    /** Adds a copy of the person to the other sheet: their name, every grade with its from-date, their terms,
462	     *  contact, tags and aliases, noting this sheet as the one they came from. Their holds, statements and watchers
463	     *  are not carried (a transfer gives them their statements, see StatementStore). */
464	    public Person copyTo(Person person, String toSheet) {
465	        Person copy = add(toSheet, person.getName(), person.gradeOn(Person.START), person.getTerms(), person.getContact(),
466	                person.getTags());
467	        person.getGrades().forEach((from, grade) -> {
468	            if (!from.equals(Person.START)) {
469	                jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)",
470	                        toSheet, copy.getId(), from, grade);
471	            }
472	        });
473	        for (String alias : person.getAliases()) {
474	            addAlias(copy, alias);
475	        }
476	        jdbc.update("UPDATE person SET origin = ? WHERE sheet_id = ? AND id = ?", person.getSheetId(), toSheet,
477	                copy.getId());
478	        return find(toSheet, copy.getId());
479	    }
480	
481	    /** Drops the person from their sheet with their grades, holds, aliases, snapshots, statements and watchers. Their claims,
482	     *  patrons and pool memberships are dropped before this (see ClaimStore, PatronStore and PoolStore). */
483	    public void remove(Person person) {
484	        String sheetId = person.getSheetId();
485	        jdbc.update("DELETE FROM person_alias WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
486	        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, person.getId());
487	        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
488	        jdbc.update("DELETE FROM person_hold WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
489	        jdbc.update("DELETE FROM person_retirement WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
490	        jdbc.update("DELETE FROM person_snapshot WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
491	        jdbc.update("DELETE FROM statement WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
492	        jdbc.update("DELETE FROM watch WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
493	    }
494	
495	    /** Makes the person's name and aliases aliases of {@code into}, then drops the person with their grades,
496	     *  holds, snapshots, statements and watchers (their contact goes with them). Their claims, patrons and pool
497	     *  memberships are moved before this (see ClaimStore, PatronStore and PoolStore). */
498	    public void mergeInto(Person person, Person into) {
499	        String sheetId = person.getSheetId();
500	        jdbc.update("UPDATE person_alias SET person_id = ? WHERE sheet_id = ? AND person_id = ?", into.getId(), sheetId,
501	                person.getId());
502	        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, person.getId());
503	        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) VALUES (?, ?, ?)", sheetId, into.getId(),
504	                person.getName());
505	        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
506	        jdbc.update("DELETE FROM person_hold WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
507	        jdbc.update("DELETE FROM person_retirement WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
508	        jdbc.update("DELETE FROM person_snapshot WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
509	        jdbc.update("DELETE FROM statement WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
510	        jdbc.update("DELETE FROM watch WHERE sheet_id = ? AND person_id = ?", sheetId, person.getId());
511	    }
512	}
