528	                + person.getName() + " grade=" + person.gradeOn(sheets.today(person.getSheetId()))
529	                + (person.isTermsChanged() ? " terms=" + (person.getTerms() == null ? "" : person.getTerms()) : "")
530	                + (person.isContactChanged() ? " contact=" + (person.getContact() == null ? "" : person.getContact()) : ""));
531	        rollups.record(person.getSheetId(), request.user(), before);
