544	/** Adds the claim (a late entry when the period its due-by falls in is soft-closed), due by the business day its person's own terms (else the terms of their grade in force on
545	 *  that date, else the sheet's terms in force then) after its date, skipping weekends and the sheet's holidays, fixed now, and logs it as DRAFT by the user at its due then. */
546	public class SaveClaimAdded {
547	    public void save(@Val ClaimInput input, @Val Person person, ClaimStore store, SettingStore settings,
548	            ClaimLogStore log, PeriodStore periods, HolidayStore holidays, Out<Claim> claim) {
549	        claim.set(add(input, person, store, settings, log, periods, holidays));
550	    }
551	
552	    static Claim add(ClaimInput input, Person person, ClaimStore store, SettingStore settings, ClaimLogStore log,
553	            PeriodStore periods, HolidayStore holidays) {
554	        int terms = termsOf(person, input.date(), settings);
555	        LocalDate dueBy = holidays.businessDaysAfter(person.getSheetId(), input.date(), terms);
556	        Claim added = store.add(person.getSheetId(), person.getId(), input.amount(), input.date(), input.note(),
557	                input.corrects(), dueBy, terms, input.ref(), input.tags());
558	        if (periods.softOn(person.getSheetId(), dueBy)) {
559	            store.markLateEntry(added);
560	        }
561	        log.record(added, input.user());
562	        return added;
563	    }
564	
565	    /** The terms a claim of the person dated {@code date} is due by: their own, else their grade's in force
566	     *  on the date, else the sheet's then. */
567	    static int termsOf(Person person, LocalDate date, SettingStore settings) {
568	        return person.getTerms() != null ? person.getTerms()
569	                : settings.terms(person.getSheetId(), person.gradeOn(date), date);
570	    }
