import { useEffect, useRef, useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { GRADES, type Person, peopleKey, useEditingPerson, usePeople } from './people';

// Adds a person, or edits the one whose editor is open (opening it fills the form with their values
// and remembers the version it loaded). A save over a version someone else has since saved is
// refused; the form then shows the person's current values and version, so saving again works.
// An edit records the grade from the from-date (the sheet's today when blank), keeping the grades
// already recorded; leaving the grade as the row shows it with the from-date blank records nothing.
// An added person's grade applies from the beginning of time. Their own terms (whole days, blank for
// none) come first when a claim's due-by is fixed. A contact (stored trimmed and lower-cased, blank
// for none) another person on the sheet has is refused. Tags are typed comma separated (stored trimmed,
// lower-cased, repeats dropped; blank for none). A refused edit closes the editor, keeping its error,
// so the next add is not taken for an edit.
function PersonForm() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [editing, setEditing] = useEditingPerson();
  const people = usePeople(sheet);
  const [name, setName] = useState('');
  const [grade, setGrade] = useState<string>('A');
  const [gradeFrom, setGradeFrom] = useState('');
  const [terms, setTerms] = useState('');
  const [contact, setContact] = useState('');
  const [tags, setTags] = useState('');
  const keepError = useRef(false);
  const [version, setVersion] = useState<number | undefined>();
  const queryClient = useQueryClient();
  const base = `/api/sheets/${encodeURIComponent(sheet)}/people`;

  const save = useMutation({
    mutationFn: (p: { name: string; grade: string; gradeFrom: string; terms: string; contact: string; tags: string }) =>
      editing
        ? putJson<Person>(`${base}/${encodeURIComponent(editing)}`, { ...p, user, version })
        : postJson<Person>(base, { ...p, user }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
      setName('');
      setGrade('A');
      clear();
    },
    onError: async (error) => {
      if (!(error instanceof HttpError && error.status === 409)) {
        if (editing) {
          keepError.current = true;
          clear();
        }
        return;
      }
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
      const current = queryClient.getQueryData<Person[]>(peopleKey(sheet))?.find((p) => String(p.id) === editing);
      if (current) fill(current);
    },
  });
  const submit = useSubmitOnce(save);
  const fill = (p: Person) => {
    setName(p.name);
    setGrade(p.grade);
    setGradeFrom('');
    setTerms(p.terms === null ? '' : String(p.terms));
    setContact(p.contact ?? '');
    setTags(p.tags.join(', '));
    setVersion(p.version);
  };
  const clear = () => {
    setName('');
    setGrade('A');
    setGradeFrom('');
    setTerms('');
    setContact('');
    setTags('');
    setVersion(undefined);
    setEditing(undefined);
  };

  const editingPerson = people.data?.find((p) => String(p.id) === editing);
  useEffect(() => {
    if (keepError.current) keepError.current = false;
    else save.reset();
    if (editingPerson) fill(editingPerson);
    // Fill only when a different editor opens, not on every re-read of the list.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [editing, editingPerson?.id]);

  return (
    <form
      data-testid="person-form"
      onSubmit={(e) => {
        e.preventDefault();
        submit({ name, grade, gradeFrom, terms, contact, tags });
      }}
    >
      <h2>{editing ? 'Edit person' : 'Add person'}</h2>
      <input
        data-testid="person-form-name"
        placeholder="Name"
        value={name}
        onChange={(e) => {
          setName(e.target.value);
          save.reset();
        }}
      />
      <select
        data-testid="person-form-grade"
        value={grade}
        onChange={(e) => {
          setGrade(e.target.value);
          save.reset();
        }}
      >
        {GRADES.map((g) => (
          <option key={g} value={g}>
            {g}
          </option>
        ))}
      </select>
      <input
        data-testid="person-form-grade-from"
        type="date"
        aria-label="Grade from (blank for the sheet's today)"
        value={gradeFrom}
        onChange={(e) => {
          setGradeFrom(e.target.value);
          save.reset();
        }}
      />
      <input
        data-testid="person-form-terms"
        inputMode="numeric"
        placeholder="Terms (days)"
        aria-label="Own terms in days (blank for none)"
        value={terms}
        onChange={(e) => {
          setTerms(e.target.value);
          save.reset();
        }}
      />
      <input
        data-testid="person-form-contact"
        placeholder="Contact"
        aria-label="Contact (blank for none)"
        value={contact}
        onChange={(e) => {
          setContact(e.target.value);
          save.reset();
        }}
      />
      <input
        data-testid="person-form-tags"
        placeholder="Tags"
        aria-label="Tags, comma separated (blank for none)"
        value={tags}
        onChange={(e) => {
          setTags(e.target.value);
          save.reset();
        }}
      />
      <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
        {editing ? 'Save' : 'Add'}
      </button>
      {editing && (
        <button
          type="button"
          data-testid="person-form-cancel"
          onClick={() => {
            save.reset();
            clear();
          }}
        >
          Cancel
        </button>
      )}
      {save.isError && (
        <span data-testid="person-form-error" role="alert">
          {' '}
          {save.error instanceof HttpError && save.error.reason ? `${save.error.reason}.` : 'A name is required.'}
        </span>
      )}
    </form>
  );
}

export const contribution = HomeMain.fill({ order: 10, Component: PersonForm });
    }

    /** Copies the person with their grades, terms, contact, tags, aliases, holds and retirements; the id of the copy. */
    private long copyPerson(Person person, String to) {
        String from = person.getSheetId();
        long id = insert("INSERT INTO person (sheet_id, name, retired_from, terms, contact, tags, list_position, origin) "
                + "SELECT ?, name, retired_from, terms, contact, tags, list_position, origin FROM person "
                + "WHERE sheet_id = ? AND id = ?", to, from, person.getId());
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) "
                + "SELECT ?, ?, from_date, grade FROM person_grade WHERE sheet_id = ? AND person_id = ?",
                to, id, from, person.getId());
        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date) "
                + "SELECT ?, ?, from_date, to_date FROM person_hold WHERE sheet_id = ? AND person_id = ? ORDER BY id",
                to, id, from, person.getId());
        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) "
                + "SELECT ?, ?, alias FROM person_alias WHERE sheet_id = ? AND person_id = ? ORDER BY id",
                to, id, from, person.getId());
        jdbc.update("INSERT INTO person_retirement (sheet_id, person_id, from_date, to_date) "
                + "SELECT ?, ?, from_date, to_date FROM person_retirement WHERE sheet_id = ? AND person_id = ? ORDER BY id",
                to, id, from, person.getId());
        return id;
    }

    private long insert(String sql, Object... args) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.statement.StatementSummary;

/** A person as the front end reads it: the grade in force on the sheet's today and every grade with the
 *  date (yyyy-MM-dd) it applies from (null for the first, from the beginning of time), with their
 *  statement count and the last statement's due-total and date (null when none was taken), whether they
 *  are retired and from when (null when not) and whether the sheet's today has reached that date, whether they have any hold
 *  and each hold's from-date and to-date (null for no end), the ids of their patrons (in the order named), and their own terms
 *  (whole days, null when none), their contact (null when none) and their aliases, sorted as names are compared, and whether they clash: their
 *  name or an alias is used as a name or alias on another sheet of the sheet's tree, and the sheet they were
 *  transferred from (null when they were not), and their past retirements, oldest first, and their tags, sorted, and their snapshots, oldest first, and their statements still standing, oldest first (by date). */
public record PersonResponse(long id, String name, String grade, List<GradeFrom> grades, long version,
        int statementCount, String statedTotal, String statementDate, boolean retired, String retiredFrom,
        boolean held, List<HoldFrom> holds, List<Long> patronIds, Integer terms,
        boolean retiredNow, String contact, List<String> aliases, boolean clashing,
        String origin, List<RetirementFrom> pastRetirements, List<String> tags,
        List<SnapshotLine> snapshots, List<StatementSummary.Line> statements) {

    /** A snapshot's day being left (yyyy-MM-dd) and the due-total as it stood then (two decimals, or n/a). */
    public record SnapshotLine(String day, String dueTotal) {
    }

    /** A past retirement's from-date and to-date, the day they were unretired (yyyy-MM-dd). */
    public record RetirementFrom(String from, String to) {
    }

    /** A hold's from-date and to-date (yyyy-MM-dd; null for no end). */
    public record HoldFrom(String from, String to) {
    }

    /** A grade and the date it applies from (null for from the beginning of time). */
    public record GradeFrom(String grade, String from) {
    }

    public static PersonResponse from(Person p, LocalDate today, StatementSummary s, List<Long> patronIds,
            boolean clashing) {
        List<GradeFrom> grades = p.getGrades().entrySet().stream()
                .map(e -> new GradeFrom(e.getValue(), Person.START.equals(e.getKey()) ? null : e.getKey().toString()))
                .toList();
        return new PersonResponse(p.getId(), p.getName(), p.gradeOn(today), grades, p.getVersion(), s.count(),
                s.lastDueTotal(), s.lastDate(), p.isRetired(),
                p.getRetiredFrom() == null ? null : p.getRetiredFrom().toString(), p.isHeld(),
                p.getHolds().stream().map(h -> new HoldFrom(h.from().toString(), h.to() == null ? null : h.to().toString()))
                        .toList(),
                patronIds, p.getTerms(), p.retiredOn(today), p.getContact(),
                List.copyOf(p.getAliases()), clashing, p.getOrigin(),
                p.getPastRetirements().stream().map(r -> new RetirementFrom(r.from().toString(), r.to().toString()))
                        .toList(),
                net.officefloor.hq.app.claim.Tags.list(p.getTags()),
                p.getSnapshots().stream().map(n -> new SnapshotLine(n.day().toString(), n.dueTotal())).toList(),
                s.lines());
    }
}
